import{z as i,x as n,o as A,c as s,q as e,j as o,D as a,d as t,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"协商与协议生成","description":"","frontmatter":{"title":"协商与协议生成","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sgt-negotiation.md","filePath":"llm/sgt-negotiation.md","lastUpdated":1791063341000}'),d={name:"llm/sgt-negotiation.md"};function p(C,E,D,F,m,c){const B=n("Mermaid");return A(),s("div",null,[E[2]||(E[2]=e('<h1 id="协商与协议生成" tabindex="-1">协商与协议生成 <a class="header-anchor" href="#协商与协议生成" aria-label="Permalink to &quot;协商与协议生成&quot;">​</a></h1><div class="epigraph"><p>辩论分胜负，协商分蛋糕：一般和的博弈里最重要的产物不是谁的策略更强，而是双方共同长出了一套没人明写的协议。</p><footer>—— 据 Crawford &amp; Sobel, Strategic Information Transmission, 1982；Bakhtin et al.（Cicero）, Science, 2022 整理</footer></div><p><a href="/llm/sgt-debate-as-game">上一课</a>把辩论读成零和导向的对抗博弈，结尾划了一条线：协商是一般和的分配博弈，不必你输我赢。本课跨过这条线。协商与协议生成是语言模型自博弈里离真实部署最近的一块——谈判、分工、接口约定、多 Agent 系统的协议——也是博弈结构最不干净的一块：利益部分冲突、信息私有、语言本身既是动作又是信号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>协商博弈的要素：双方对结果有部分一致的偏好（都有蛋糕比没蛋糕好），分配比例才是冲突；私有信息（底线、偏好、保留价）不可直接观测，只能通过话语传递。博弈论早就指出这种「廉价磋商」（cheap talk）的脆弱性：Crawford 与 Sobel 1982 证明，当双方利益完全一致时话语可被完全相信，利益严重分歧时有意义的信息传递会碎裂成粗糙的分区——发话人的话最多能表达「我属于哪一档」，精度受利益对齐程度封顶。也就是说，<strong>没有约束的承诺不可信</strong>，协商的效力天然受利益结构限制。</p><p><span class="marginnote">「廉价磋商」就是不用付代价的空口白话：说错不罚、说到不奖。它能不能被信，取决于双方利益有多一致——卖房中介说「这房没问题」你多半打个折，因为他的佣金和你扛房贷的利益不完全重合；利益越一致，空话才越接近真话。</span></p><p>这条结论先于任何模型存在，却是所有 LLM 协商实验的第一块试金石。Deal or No Deal（Lewis 等 2018）用端到端协商对话训练出会讨价还价的 Agent：模型自发发展出锚定报价、假装不在乎等策略，也暴露了廉价磋商的阴暗面——优化成交率的 Agent 学会了说「我也在乎 X」然后立刻让步，承诺与行为脱钩。Crawford–Sobel 的分区结论在这里原样兑现：话语的说服力受「听者为何该信」的结构限制。</p><h3 id="从对话到协议" tabindex="-1">从对话到协议 <a class="header-anchor" href="#从对话到协议" aria-label="Permalink to &quot;从对话到协议&quot;">​</a></h3><p>更深的层次是<strong>协议生成</strong>：双方不仅交换报价，还共同建立后续交互的约定——什么算违约、如何分工、信号代表什么。Lewis 1969 对约定的分析指出约定可以自生成：一次成功的协调会成为先例，先例成为下次的默认。Axelrod 1984 的囚徒困境锦标赛给出另一半答案：在重复交互里，「一报还一报」这类简单、可预测、报复性与宽容性并存的策略胜出——<strong>可预测性本身就是协议</strong>，对手能预判你，才敢与你合作。Cicero（Bakhtin 等 2022）在 Diplomacy 上把两半合体：语言模型负责说人话，规划模块负责在博弈树上选动作，二者用「战略性推理过滤话语」粘合，达到人类水平——它的关键工程恰是让语言承诺与后续行动保持一致，否则盟友下一个回合就不再信你。</p><p><span class="marginnote">Diplomacy 是协商的极限考场：七人博弈、回合间私密通话、承诺无外部强制执行。Cicero 达到人类水平靠的分工是「语言出、规划收」——纯端到端语言模型在该任务上尚无同等证据。</span></p>',10)),(A(),o(l,null,{default:a(()=>[r(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E5%81%8F%E5%A5%BD%20%2B%20%E7%A7%81%E6%9C%89%E4%BF%A1%E6%81%AF%22%5D%20--%3E%20TALK%5B%22%E5%BB%89%E4%BB%B7%E7%A3%8B%E5%95%86%EF%BC%9A%E6%97%A0%E7%BA%A6%E6%9D%9F%E8%AF%9D%E8%AF%AD%22%5D%0A%20%20TALK%20--%3E%20Q%7B%22%E5%88%A9%E7%9B%8A%E5%AF%B9%E9%BD%90%E7%A8%8B%E5%BA%A6%22%7D%0A%20%20Q%20--%3E%7C%22%E9%AB%98%E5%BA%A6%E4%B8%80%E8%87%B4%22%7C%20FULL%5B%22%E8%AF%9D%E8%AF%AD%E5%8F%AF%E4%BF%A1%EF%BC%8C%E4%BF%A1%E6%81%AF%E5%85%A8%E4%BC%A0%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%A5%E9%87%8D%E5%88%86%E6%AD%A7%22%7C%20PART%5B%22%E4%BF%A1%E6%81%AF%E7%A2%8E%E6%88%90%E7%B2%97%E7%B3%99%E5%88%86%E5%8C%BA%22%5D%0A%20%20PART%20--%3E%20REP%5B%22%E9%87%8D%E5%A4%8D%E4%BA%A4%E4%BA%92%EF%BC%9A%E5%8F%AF%E9%A2%84%E6%B5%8B%E7%AD%96%E7%95%A5%E6%8D%A2%E4%BF%A1%E4%BB%BB%22%5D%0A%20%20REP%20--%3E%20CONV%5B%22%E7%BA%A6%E5%AE%9A%E8%87%AA%E7%94%9F%E6%88%90%EF%BC%9A%E5%85%88%E4%BE%8B%E5%8F%98%E9%BB%98%E8%AE%A4%22%5D%0A%20%20CONV%20--%3E%20CIC%5B%22%E8%AF%AD%E8%A8%80%E6%89%BF%E8%AF%BA%E4%B8%8E%E8%A7%84%E5%88%92%E8%A1%8C%E5%8A%A8%E4%B8%80%E8%87%B4%EF%BC%9ACicero%20%E8%B7%AF%E7%BA%BF%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>定理当试金石加案例解剖</strong>：先立 Crawford–Sobel 的廉价磋商封顶作第一块试金石，再取 Deal or No Deal 与 Cicero 两案核对——模型习得的策略与脱钩承诺是否兑现了定理的预言；协议生成一侧借 Lewis 的约定论与 Axelrod 的锦标赛结论，提炼「可预测性换合作」的成立条件。评测随之换方法：不评单局得分，评约定的跨对手存活率，以区分协议与共谋代码。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>协商自博弈的训练机制与辩论的最大差异在奖励：辩论是选边（稀疏、零和），协商是分配（连续、一般和），可以真双赢也可以双输， 于是「对手课程」失去方向感——打不过对手未必是坏事（合作失败），赢太多可能是灾难（分蛋糕全拿走，下轮没人来）。塑形因此必须编码<strong>关系性</strong>指标：总剩余（有没有把蛋糕做大）、公平性（分配是否可持续）、承诺兑现率（说好的做没做）。这些恰是主干课自博弈课程里没有的信号类型；不引入它们，纯优化己方收益的协商 Agent 会收敛到机会主义均衡——短期最优、长期无人合作，Axelrod 1970 年代的教训以模型形式重演。</p><p>这张图回答的问题是：只优化己方收益会滑向哪里，三个关系性指标各自在拦什么。</p>',5)),(A(),o(l,null,{default:a(()=>[r(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20ONLY%5B%22%E5%8F%AA%E4%BC%98%E5%8C%96%E5%B7%B1%E6%96%B9%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20OPP%5B%22%E6%9C%BA%E4%BC%9A%E4%B8%BB%E4%B9%89%E5%9D%87%E8%A1%A1%EF%BC%9A%E8%BF%99%E4%B8%80%E5%B1%80%E5%85%A8%E6%8B%BF%22%5D%0A%20%20OPP%20--%3E%20NOCOM%5B%22%E4%B8%8B%E4%B8%80%E5%B1%80%E6%97%A0%E4%BA%BA%E4%B8%8E%E4%BD%A0%E5%90%88%E4%BD%9C%22%5D%0A%20%20REL%5B%22%E5%A1%91%E5%BD%A2%E5%85%B3%E7%B3%BB%E6%80%A7%E6%8C%87%E6%A0%87%22%5D%20--%3E%20SUR%5B%22%E6%80%BB%E5%89%A9%E4%BD%99%EF%BC%9A%E8%9B%8B%E7%B3%95%E6%9C%89%E6%B2%A1%E6%9C%89%E5%81%9A%E5%A4%A7%22%5D%0A%20%20REL%20--%3E%20FAIR%5B%22%E5%85%AC%E5%B9%B3%E6%80%A7%EF%BC%9A%E5%88%86%E6%B3%95%E5%8F%AF%E4%B8%8D%E5%8F%AF%E6%8C%81%E7%BB%AD%22%5D%0A%20%20REL%20--%3E%20KEEP%5B%22%E5%85%91%E7%8E%B0%E7%8E%87%EF%BC%9A%E8%AF%B4%E5%A5%BD%E7%9A%84%E5%81%9A%E6%B2%A1%E5%81%9A%22%5D%0A%20%20SUR%20--%3E%20SUS%5B%22%E9%95%BF%E6%9C%9F%E5%90%88%E4%BD%9C%E5%8F%AF%E6%8C%81%E7%BB%AD%22%5D%0A%20%20FAIR%20--%3E%20SUS%0A%20%20KEEP%20--%3E%20SUS%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p>协议生成的评测同样机制化：不评单局得分，评<strong>约定的存活率</strong>——双方自发长出的信号系统在换对手、换任务后是否仍被使用与理解。这与<a href="/llm/sgt-debate-as-game">辩论作为博弈</a>的辩题隔离逻辑同构：训练中长出的协议只对训练对手有意义，必须跨对手复测，才能区分「协议」与「共谋代码」。</p><p><span class="marginnote">数字实例：一块蛋糕值 10 分。你全拿走，这局得 10，但对手下局宁可不谈，你的长期总收入停在 10；各拿 5，十局下来是 50。公平性指标管的就是这笔长期账——它惩罚的不是「这局少赚」，而是「把谈判桌拆了」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>廉价磋商的封顶仍在：模型间的协议没有外部执行机制时，遵守协议是策略选择不是义务，利益一大冲突就会违约——工程上要么引入可验证承诺（押注、事后审计），要么把交互设计成重复博弈让声誉起作用，二选一，没有第三条路。</p><p><span class="marginnote">常见误区：以为合作安全全靠合同条款。重复博弈给出另一条路——声誉：把一次性交易变成「下次还见面」，这次违约省下的蝇头小利，抵不上失去对方未来所有合作。这就是「没有第三条路」里第二条的实际工作原理。</span>评测边界：人类谈判数据的协议不能直接迁移给 LLM——人口统计与谈判风格的分布不同，所得「人类水平」是分布内的错觉。与下一课的接口：协商暴露了一个更大的问题——「协议如何形成」其实是「规则如何被设计」的特例；把视角从参与者换成规则制定者，就是机制设计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>协商是一般和博弈：偏好部分一致、信息私有，廉价磋商定理（Crawford–Sobel 1982）给话语可信度封顶。</li><li>Deal or No Deal 显示 LLM 能习得谈判策略也会习得脱钩承诺；可信协商需要结构而非话术。</li><li>协议自生成：先例成默认（Lewis 1969），重复博弈中可预测性换合作（Axelrod 1984）。</li><li>Cicero 的路线是语言承诺与规划行动保持一致，不是端到端对谈。</li><li>协商自博弈要塑形关系性指标（总剩余、公平、兑现率），评测约定存活率而非单局得分。</li><li>出处：Crawford 与 Sobel 1982；Lewis 等 2018；Lewis 1969；Axelrod 1984；Bakhtin 等 2022（Cicero）。</li></ul>',7))])}const g=i(d,[["render",p]]);export{_ as __pageData,g as default};
